const labels={goal:"Goal",idea:"Idea",initiative:"Initiative",problem:"Problem",customer:"Customer",product:"Product",market:"Market",decision:"Decision",option:"Option",risk:"Risk",dependency:"Dependency",constraint:"Constraint",fact:"Fact",assumption:"Assumption",metric:"Metric",experiment:"Experiment",unknown:"Unknown",investment:"Investment",cost:"Cost",revenue:"Revenue",runway:"Runway",people:"People",future_plan:"Future plan"};
const family=n=>["metric","investment","cost","revenue","runway"].includes(n.type)?"money":["risk","problem","dependency","constraint"].includes(n.type)?"risk":["people","customer"].includes(n.type)?"people":["decision","option"].includes(n.type)?"choice":["assumption","experiment","unknown"].includes(n.type)?"unknown":n.type==="goal"?"goal":n.type==="future_plan"?"future":"build";
