const canvas=$("#canvas"),ctx=canvas.getContext("2d"),input=$("#input"),inspector=$("#inspector"),body=$("#body"),empty=$("#empty");
const all=()=>[{id:"root",title:graph.root.title,type:"root",x:0,y:0,vx:0,vy:0},...graph.nodes],get=id=>all().find(n=>n.id===id),hash=x=>{const y=Math.sin(x*91.17)*43758.5;return y-Math.floor(y)};
const resize=()=>{const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0);draw()};
const screen=n=>({x:canvas.clientWidth/2+(n.x||0)*scale+panX,y:canvas.clientHeight/2+(n.y||0)*scale+panY}),world=(x,y)=>({x:(x-canvas.clientWidth/2-panX)/scale,y:(y-canvas.clientHeight/2-panY)/scale});
const radius=n=>n.id==="root"?26:Math.min(22,10+graph.edges.filter(e=>e.source===n.id||e.target===n.id).length*1.8+(n.proposal?2:0));
function draw(){ctx.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);ctx.fillStyle="#090b10";ctx.fillRect(0,0,canvas.clientWidth,canvas.clientHeight);const ns=all(),m=new Map(ns.map(n=>[n.id,n]));
graph.edges.forEach((e,i)=>{const a=m.get(e.source),b=m.get(e.target);if(!a||!b)return;const A=screen(a),B=screen(b),dx=(b.x||0)-(a.x||0),dy=(b.y||0)-(a.y||0),l=Math.hypot(dx,dy)||1,bend=(hash(i+7)-.5)*100,C=screen({x:(a.x+b.x)/2-dy/l*bend,y:(a.y+b.y)/2+dx/l*bend});ctx.beginPath();ctx.moveTo(A.x,A.y);ctx.quadraticCurveTo(C.x,C.y,B.x,B.y);ctx.strokeStyle=selected===e.source||selected===e.target?"rgba(139,124,255,.7)":"rgba(120,130,150,.22)";ctx.lineWidth=selected===e.source||selected===e.target?2:1;ctx.setLineDash(e.kind==="structural"?[]:[5,7]);ctx.stroke();ctx.setLineDash([])});
ns.forEach(n=>{const s=screen(n),r=radius(n),sel=n.id===selected,match=!query||n.title.toLowerCase().includes(query)||label(n).toLowerCase().includes(query);ctx.save();if(query&&!match)ctx.globalAlpha=.14;if(sel){ctx.shadowBlur=30;ctx.shadowColor="#8b7cff"}ctx.beginPath();ctx.arc(s.x,s.y,r,0,Math.PI*2);ctx.fillStyle="#11151e";ctx.fill();ctx.lineWidth=sel?2.5:1.2;ctx.strokeStyle=n.id==="root"?"#8b7cff":({money:"#f2b96b",risk:"#ff6b81",people:"#61d6c7",choice:"#9b8cff",unknown:"#c3a6ff",goal:"#9ea7ff",future:"#73b8ff",build:"#7e8798"}[family(n)]||"#7e8798");ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle="#edf0f6";ctx.font=(sel?"600 ":"500 ")+(n.id==="root"?13:12)+"px Inter,system-ui,sans-serif";ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText(n.title.length>24?n.title.slice(0,23)+"…":n.title,s.x,s.y+r+16);if(n.proposal){ctx.font="9px Inter";ctx.fillStyle="#b8a8ff";ctx.fillText("AI BLIND SPOT",s.x,s.y-r-10)}ctx.restore()})}
function seed(){const ns=all();ns[0].x=0;ns[0].y=0;ns.slice(1).forEach((n,i)=>{if(n.x==null){const a=i/ns.length*Math.PI*2,r=150+i*18;n.x=Math.cos(a)*r;n.y=Math.sin(a)*r}})}
function simulate(frames=150){let f=0;const tick=()=>{const ns=all(),m=new Map(ns.map(n=>[n.id,n]));ns.slice(1).forEach(n=>{n.vx??=0;n.vy??=0;let ax=-(n.x||0)*.0025,ay=-(n.y||0)*.0025;ns.forEach(o=>{if(o===n)return;let dx=(n.x||0)-(o.x||0),dy=(n.y||0)-(o.y||0),q=5000/(dx*dx+dy*dy+500);ax+=dx*q;ay+=dy*q});graph.edges.filter(e=>e.source===n.id||e.target===n.id).forEach(e=>{const o=m.get(e.source===n.id?e.target:e.source);if(!o)return;const dx=(o.x||0)-(n.x||0),dy=(o.y||0)-(n.y||0),d=Math.hypot(dx,dy)||1,q=(d-190)*.0008;ax+=dx/d*q;ay+=dy/d*q});n.vx=(n.vx+ax)*.88;n.vy=(n.vy+ay)*.88;n.x+=n.vx;n.y+=n.vy});draw();if(++f<frames)requestAnimationFrame(tick)};tick()}
function fit(){const ns=all(),xs=ns.map(n=>n.x||0),ys=ns.map(n=>n.y||0),bw=Math.max(...xs)-Math.min(...xs),bh=Math.max(...ys)-Math.min(...ys);scale=Math.min(1.5,Math.max(.35,Math.min((canvas.clientWidth-140)/(bw+240),(canvas.clientHeight-140)/(bh+240))));panX=-(Math.min(...xs)+Math.max(...xs))/2*scale;panY=-(Math.min(...ys)+Math.max(...ys))/2*scale;draw()}
function inspect(id){selected=id;chat=[];const n=get(id),rel=graph.edges.filter(e=>e.source===id||e.target===id).map(e=>get(e.source===id?e.target:e.source)).filter(Boolean);$("#nodeType").textContent=label(n).toUpperCase();$("#nodeTitle").textContent=n.title;body.innerHTML='<div class="summary">'+esc(n.details||n.summary||"Nothing recorded yet. Tell FounderOS more, or ask below.")+'</div>'+(n.confidence!=null?'<div class="confidence"><span>Confidence <b>'+n.confidence+'%</b></span><i style="width:'+n.confidence+'%"></i></div>':"")+'<section><label>Connected thinking</label><div class="chips">'+(rel.slice(0,12).map(x=>'<button data-node="'+esc(x.id)+'">'+esc(x.title)+'</button>').join("")||"<em>No connected nodes yet.</em>")+'</div></section>'+(n.proposal?'<section class="proposal"><small>AI PROPOSAL</small><p>This is a question, not a fact. You decide whether it belongs on your map.</p><div><button class="primary" data-prop="accept">Accept</button><button data-prop="ignore">Ignore</button><button data-prop="reject">Reject</button></div></section>':"")+'<section class="coach"><label>Founder Coach</label><small>Context-aware · '+rel.length+' connected nodes</small><div class="thread" id="thread"></div><div class="ask"><input id="ask" placeholder="Ask about this node…"><button id="send">↑</button></div></section>';body.querySelectorAll("[data-node]").forEach(b=>b.onclick=()=>inspect(b.dataset.node));body.querySelectorAll("[data-prop]").forEach(b=>b.onclick=()=>resolve(b.dataset.prop));$("#send").onclick=sendChat;$("#ask").addEventListener("keydown",e=>{if(e.key==="Enter")sendChat()});inspector.classList.add("open");draw()}
function renderChat(){const t=$("#thread");if(t)t.innerHTML=chat.map(x=>'<div class="bubble '+x.role+'">'+esc(x.content)+'</div>').join("")}
async function sendChat(){const el=$("#ask"),q=el.value.trim();if(!q)return;chat.push({role:"user",content:q});el.value="";renderChat();el.disabled=true;try{const r=await api("/api/graph/chat",{method:"POST",body:JSON.stringify({nodeId:selected,question:q,history:chat,mode:"founder",...provider})});chat.push({role:"assistant",content:r.reply||r.brief?.summary||"No response."})}catch(e){chat.push({role:"assistant",content:e.message||"The coach is unavailable."})}finally{el.disabled=false;renderChat()}}
async function resolve(action){try{graph=await api("/api/graph/proposal",{method:"POST",body:JSON.stringify({nodeId:selected,action})});seed();render();inspect(selected)}catch(e){alert(e.message)}}
function localMap(text){const t=text.trim(),low=t.toLowerCase(),specs=[["product","Product","product"],["build","Build","initiative"],["customer","Customers","customer"],["sales","Sales","initiative"],["marketing","Marketing","initiative"],["hire","Hiring","people"],["cto","CTO Hire","people"],["fund","Funding","investment"],["raise","Funding","investment"],["runway","Runway","runway"],["money","Money","cost"],["cost","Costs","cost"],["price","Pricing","decision"],["pricing","Pricing","decision"],["risk","Risk","risk"],["tax","Tax","constraint"],["launch","Launch","initiative"],["future","Future Plan","future_plan"],["idea","Idea","idea"],["problem","Problem","problem"],["legal","Legal / Compliance","constraint"]];const nodes=[],seen=new Set();for(const [key,title,type] of specs)if(low.includes(key)&&!seen.has(title)){seen.add(title);nodes.push({id:"local-"+title.toLowerCase().replace(/[^a-z0-9]+/g,"-"),title,type,state:"known",confidence:55,summary:t.slice(0,120),details:t,capital:{amount:null,currency:"INR",status:"none"},evidence:[t],assumptions:[],dependencies:[],proposal:false,status:"active"})}if(!nodes.length)nodes.push({id:"local-thought",title:"Founder thought",type:"idea",state:"known",confidence:50,summary:t.slice(0,120),details:t,capital:{amount:null,currency:"INR",status:"none"},evidence:[t],assumptions:[],dependencies:[],proposal:false,status:"active"});return{root:{title:graph.root?.title||"Your startup",summary:t,objective:""},nodes,edges:nodes.map(n=>({source:"root",target:n.id,kind:"structural",relationship:"contains",confidence:35})),insights:[],questions:[]}}
async function mapThought(text){if(!text.trim())return;$("#map").disabled=true;$("#map").textContent="Mapping…";try{graph=localMap(text);input.value="";seed();render();fit();simulate(90);try{const remote=await Promise.race([api("/api/graph/extract",{method:"POST",body:JSON.stringify({text,...provider})}),new Promise((_,rej)=>setTimeout(()=>rej(new Error("AI request timed out")),7000))]);if(remote?.nodes){graph=remote;seed();render();fit();simulate(120)}}catch(e){console.warn("AI unavailable; keeping local map",e)}}finally{$("#map").disabled=false;$("#map").textContent="Map ↗"}}
async function chooseProvider(){const key=prompt("Optional OpenRouter-compatible API key. Leave blank for FounderOS Free AI.");if(!key){provider={provider:"free"};return}provider={provider:"byok",apiKey:key,llmModel:prompt("Model","qwen/qwen3.8-27b:free")||"qwen/qwen3.8-27b:free",llmBaseUrl:prompt("Base URL","https://openrouter.ai/api/v1")||"https://openrouter.ai/api/v1"};$("#providerLabel").textContent="My API key"}
function render(){seed();$("#rootTitle").textContent=graph.root.title||"Your startup";$("#count").textContent=graph.nodes.length+" nodes · "+graph.edges.length+" connections";empty.classList.toggle("hidden",!!graph.nodes.length);draw();if(inspector.classList.contains("open"))inspect(selected)}
$("#composer").onsubmit=e=>{e.preventDefault();mapThought(input.value)};$("#close").onclick=()=>inspector.classList.remove("open");$("#fit").onclick=fit;$("#provider").onclick=chooseProvider;$("#new").onclick=()=>input.focus();$("#search").oninput=e=>{query=e.target.value.toLowerCase();draw()};input.oninput=()=>{input.style.height="auto";input.style.height=Math.min(160,input.scrollHeight)+"px"};document.querySelectorAll("[data-example]").forEach(b=>b.onclick=()=>{input.value=b.dataset.example;input.focus()});
canvas.onwheel=e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top,b=world(mx,my),z=Math.exp(-e.deltaY*.001);scale=Math.max(.25,Math.min(3,scale*z));const a=screen({x:b.x,y:b.y});panX+=mx-a.x;panY+=my-a.y;draw()};
canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;drag=null;for(const n of all()){const s=screen(n);if(Math.hypot(x-s.x,y-s.y)<radius(n)+12){drag=n.id;break}}last={x,y};moved=false;panning=!drag};
canvas.onpointermove=e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(drag){const n=get(drag),p=world(x,y);n.x=p.x;n.y=p.y;n.vx=0;n.vy=0;moved=true;draw()}else if(panning){panX+=x-last.x;panY+=y-last.y;last={x,y};moved=true;draw()}};
